mapper.select:
SELECT * FROM ( SELECT ROWNUM rn, m.* FROM ( SELECT p.product_id, p.product_name, p.price, NVL(SUM(s.quantity), 0) AS quantity, p.unit, i.file_path AS image_path, i.save_name, c.category_path, p.status FROM product p LEFT JOIN stock s ON p.product_id = s.product_id LEFT JOIN product_image i ON p.image_id = i.image_id LEFT JOIN ( SELECT category_id, LTRIM(SYS_CONNECT_BY_PATH(category_name,'>'),'>') AS category_path FROM category START WITH parent_id IS NULL CONNECT BY PRIOR category_id = parent_id ) c ON p.category_id = c.category_id
(p.product_name LIKE '%'||#{keyword}||'%' OR c.category_path LIKE '%'||#{keyword}||'%')
AND p.status = #{status}
GROUP BY p.product_id, p.product_name, p.price, p.unit, i.file_path, i.save_name, c.category_path, p.status
ORDER BY p.product_id ) m )
WHERE rn >= #{startRow} AND rn <= #{endRow}

mapper.update:
UPDATE STOCK
SET quantity = #{quantity}
WHERE stock_id=#{stock_id}
